import React, { useMemo, useRef, useState } from 'react';
import {
  X,
  MessageSquare,
  CalendarPlus,
  FileText,
  Download,
  ImageDown,
  Pencil,
  ShieldCheck,
  Clock3,
  MapPin,
  Phone,
  CheckCircle2,
  AlertCircle,
  XCircle,
  Sparkles,
  Smartphone,
  Home,
  Wrench,
} from 'lucide-react';
import { Quote } from '../types';
import { formatDateBR, formatCurrencyBRL } from '../utils/date';

const MAICON_LOGO = 'data:image/png;base64,';

interface QuoteDetailModalProps {
  quote: Quote | null;
  isOpen: boolean;
  onClose: () => void;
  onOpenWhatsApp: (quote: Quote) => void;
  onConvertToAppointment: (quote: Quote) => void;
  onEditQuote: (quote: Quote) => void;
}

const sanitizeFileName = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();

const addDays = (isoDate: string, days: number) => {
  const [year, month, day] = isoDate.slice(0, 10).split('-').map(Number);
  const d = new Date(year, month - 1, day);
  d.setDate(d.getDate() + Math.max(0, days));
  return d.toISOString().slice(0, 10);
};

export const QuoteDetailModal: React.FC<QuoteDetailModalProps> = ({
  quote,
  isOpen,
  onClose,
  onOpenWhatsApp,
  onConvertToAppointment,
  onEditQuote,
}) => {
  const documentRef = useRef<HTMLDivElement>(null);
  const [exporting, setExporting] = useState<'image' | 'pdf' | null>(null);

  const validUntil = useMemo(
    () => (quote ? addDays(quote.date, quote.validityDays) : ''),
    [quote]
  );

  if (!isOpen || !quote) return null;

  const getStatusBadge = (status: Quote['status']) => {
    const config = {
      aprovado: { icon: CheckCircle2, text: 'Aprovado', className: 'bg-emerald-100 text-emerald-800 border-emerald-200' },
      convertido: { icon: CalendarPlus, text: 'Convertido', className: 'bg-cyan-100 text-cyan-800 border-cyan-200' },
      recusado: { icon: XCircle, text: 'Recusado', className: 'bg-rose-100 text-rose-800 border-rose-200' },
      pendente: { icon: AlertCircle, text: 'Pendente', className: 'bg-amber-100 text-amber-800 border-amber-200' },
    }[status];
    const Icon = config.icon;
    return (
      <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.12em] ${config.className}`}>
        <Icon className="h-3 w-3" />
        {config.text}
      </span>
    );
  };

  const capture = async () => {
    // Geração por Canvas 2D: mais confiável no Android/Brave/Chrome do que
    // converter o DOM para SVG/foreignObject.
    const width = 1080;
    const margin = 56;
    const contentWidth = width - margin * 2;
    const itemRowHeight = 74;
    const itemsHeight = Math.max(1, quote.items.length) * itemRowHeight;
    const notesExtra = quote.notes ? 120 : 0;
    const height = 1540 + itemsHeight + notesExtra;
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas indisponível.');

    const CYAN = '#16b9db';
    const BLUE = '#1570c8';
    const DARK = '#0b1016';
    const TEXT = '#111827';
    const MUTED = '#64748b';
    const LIGHT = '#f3f7fa';
    const BORDER = '#d8e1e8';

    const roundedRect = (x: number, y: number, w: number, h: number, r = 22) => {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    };

    const fillRound = (x: number, y: number, w: number, h: number, fill: string, r = 22) => {
      ctx.fillStyle = fill;
      roundedRect(x, y, w, h, r);
      ctx.fill();
    };

    const strokeRound = (x: number, y: number, w: number, h: number, stroke: string, r = 22) => {
      ctx.strokeStyle = stroke;
      ctx.lineWidth = 2;
      roundedRect(x, y, w, h, r);
      ctx.stroke();
    };

    const wrapText = (
      text: string,
      x: number,
      y: number,
      maxWidth: number,
      lineHeight: number,
      maxLines = 4
    ) => {
      const words = String(text || '').split(/\s+/).filter(Boolean);
      if (!words.length) return y;
      let line = '';
      let lineNo = 0;
      for (let i = 0; i < words.length; i += 1) {
        const test = line ? `${line} ${words[i]}` : words[i];
        if (ctx.measureText(test).width > maxWidth && line) {
          ctx.fillText(line, x, y + lineNo * lineHeight);
          lineNo += 1;
          line = words[i];
          if (lineNo >= maxLines - 1) {
            const rest = [line, ...words.slice(i + 1)].join(' ');
            let clipped = rest;
            while (clipped.length > 3 && ctx.measureText(`${clipped}…`).width > maxWidth) {
              clipped = clipped.slice(0, -1);
            }
            ctx.fillText(`${clipped}…`, x, y + lineNo * lineHeight);
            return y + (lineNo + 1) * lineHeight;
          }
        } else {
          line = test;
        }
      }
      ctx.fillText(line, x, y + lineNo * lineHeight);
      return y + (lineNo + 1) * lineHeight;
    };

    const label = (text: string, x: number, y: number) => {
      ctx.fillStyle = MUTED;
      ctx.font = '700 21px Arial, sans-serif';
      ctx.fillText(text.toUpperCase(), x, y);
    };

    const value = (text: string, x: number, y: number, size = 30) => {
      ctx.fillStyle = TEXT;
      ctx.font = `700 ${size}px Arial, sans-serif`;
      ctx.fillText(text, x, y);
    };

    const loadImage = (src: string) =>
      new Promise<HTMLImageElement>((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = () => reject(new Error('Falha ao carregar a logo.'));
        image.src = src;
      });

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // Cabeçalho
    ctx.fillStyle = DARK;
    ctx.fillRect(0, 0, width, 270);
    const grad = ctx.createLinearGradient(690, 0, 980, 260);
    grad.addColorStop(0, BLUE);
    grad.addColorStop(1, CYAN);
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(770, 0);
    ctx.lineTo(1010, 0);
    ctx.lineTo(855, 270);
    ctx.lineTo(675, 270);
    ctx.closePath();
    ctx.fill();

    try {
      const logo = await loadImage(MAICON_LOGO);
      const maxW = 470;
      const maxH = 210;
      const ratio = Math.min(maxW / logo.width, maxH / logo.height);
      const logoW = logo.width * ratio;
      const logoH = logo.height * ratio;
      ctx.drawImage(logo, margin, 28, logoW, logoH);
    } catch (error) {
      console.warn(error);
      ctx.fillStyle = '#ffffff';
      ctx.font = '900 42px Arial, sans-serif';
      ctx.fillText('MAICON', margin, 95);
      ctx.fillStyle = CYAN;
      ctx.fillText('AUTOMAÇÃO', margin, 145);
    }

    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'right';
    ctx.font = '700 24px Arial, sans-serif';
    ctx.fillText('TECNOLOGIA PARA UM', width - margin, 82);
    ctx.fillText('DIA A DIA MAIS SEGURO', width - margin, 116);
    ctx.fillStyle = CYAN;
    ctx.fillRect(width - margin - 180, 136, 180, 6);
    ctx.textAlign = 'left';

    // Título
    ctx.fillStyle = TEXT;
    ctx.font = '900 66px Arial, sans-serif';
    ctx.fillText('ORÇAMENTO', margin, 355);
    ctx.fillStyle = CYAN;
    ctx.fillRect(margin, 378, 190, 6);
    ctx.fillStyle = MUTED;
    ctx.font = '600 24px Arial, sans-serif';
    ctx.fillText('SOLUÇÕES EM FECHADURAS ELETRÔNICAS', margin, 416);

    // Dados do cliente
    const cardY = 462;
    const gap = 20;
    const leftW = 600;
    const rightW = contentWidth - leftW - gap;
    fillRound(margin, cardY, leftW, 250, LIGHT, 24);
    strokeRound(margin, cardY, leftW, 250, BORDER, 24);
    fillRound(margin + leftW + gap, cardY, rightW, 250, LIGHT, 24);
    strokeRound(margin + leftW + gap, cardY, rightW, 250, BORDER, 24);

    label('Cliente', margin + 28, cardY + 42);
    value(quote.clientName || 'Cliente', margin + 28, cardY + 82, 28);
    label('Contato', margin + 28, cardY + 125);
    value(quote.clientPhone || 'Não informado', margin + 28, cardY + 164, 27);
    label('Endereço', margin + 28, cardY + 207);
    ctx.fillStyle = TEXT;
    ctx.font = '700 23px Arial, sans-serif';
    wrapText(quote.address || 'A combinar', margin + 150, cardY + 207, leftW - 180, 27, 2);
    ctx.fillStyle = MUTED;
    ctx.font = '500 20px Arial, sans-serif';
    ctx.fillText(
      [quote.neighborhood && `Bairro: ${quote.neighborhood}`, quote.city && `Cidade: ${quote.city}`]
        .filter(Boolean)
        .join('  |  ') || ' ',
      margin + 28,
      cardY + 238
    );

    const rx = margin + leftW + gap + 26;
    label('Data', rx, cardY + 42);
    value(formatDateBR(quote.date), rx, cardY + 78, 26);
    label('Validade', rx, cardY + 122);
    value(`${quote.validityDays} dias`, rx, cardY + 158, 26);
    ctx.fillStyle = MUTED;
    ctx.font = '500 19px Arial, sans-serif';
    ctx.fillText(`Até ${formatDateBR(validUntil)}`, rx, cardY + 186);
    label('Nº do orçamento', rx, cardY + 222);
    value(quote.code, rx + 200, cardY + 222, 24);

    // Tabela
    let y = 752;
    const colItem = 78;
    const colValue = 190;
    const colWarranty = 190;
    fillRound(margin, y, contentWidth, 62, DARK, 18);
    ctx.fillStyle = '#ffffff';
    ctx.font = '800 21px Arial, sans-serif';
    ctx.fillText('ITEM', margin + 18, y + 39);
    ctx.fillText('DESCRIÇÃO DO SERVIÇO / PRODUTO', margin + colItem + 20, y + 39);
    ctx.fillText('GARANTIA', margin + contentWidth - colValue - colWarranty + 25, y + 39);
    ctx.textAlign = 'right';
    ctx.fillText('VALOR', margin + contentWidth - 22, y + 39);
    ctx.textAlign = 'left';
    y += 62;

    quote.items.forEach((item, index) => {
      ctx.fillStyle = index % 2 === 0 ? '#ffffff' : '#f9fbfc';
      ctx.fillRect(margin, y, contentWidth, itemRowHeight);
      ctx.strokeStyle = BORDER;
      ctx.lineWidth = 1;
      ctx.strokeRect(margin, y, contentWidth, itemRowHeight);
      ctx.fillStyle = TEXT;
      ctx.font = '700 22px Arial, sans-serif';
      ctx.fillText(String(index + 1), margin + 30, y + 44);
      ctx.font = '600 22px Arial, sans-serif';
      wrapText(item.description, margin + colItem + 20, y + 30, contentWidth - colItem - colValue - colWarranty - 45, 26, 2);
      ctx.fillStyle = MUTED;
      ctx.font = '600 20px Arial, sans-serif';
      ctx.fillText(quote.warrantyInfo || '—', margin + contentWidth - colValue - colWarranty + 25, y + 43);
      ctx.fillStyle = TEXT;
      ctx.textAlign = 'right';
      ctx.font = '800 22px Arial, sans-serif';
      ctx.fillText(formatCurrencyBRL(item.total), margin + contentWidth - 22, y + 44);
      ctx.textAlign = 'left';
      y += itemRowHeight;
    });

    // Total
    y += 22;
    fillRound(margin + contentWidth - 370, y, 370, 72, LIGHT, 16);
    ctx.fillStyle = TEXT;
    ctx.font = '800 26px Arial, sans-serif';
    ctx.fillText('TOTAL', margin + contentWidth - 345, y + 46);
    fillRound(margin + contentWidth - 225, y, 225, 72, CYAN, 16);
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.font = '900 30px Arial, sans-serif';
    ctx.fillText(formatCurrencyBRL(quote.totalAmount), margin + contentWidth - 112, y + 46);
    ctx.textAlign = 'left';

    // Condições e inclusões
    y += 112;
    const half = (contentWidth - gap) / 2;
    const infoH = quote.notes ? 320 : 250;
    fillRound(margin, y, half, infoH, LIGHT, 24);
    fillRound(margin + half + gap, y, half, infoH, LIGHT, 24);

    ctx.fillStyle = TEXT;
    ctx.font = '900 25px Arial, sans-serif';
    ctx.fillText('INCLUSO NO SERVIÇO', margin + 28, y + 48);
    ctx.fillStyle = CYAN;
    ctx.font = '700 21px Arial, sans-serif';
    ['✓  Mão de obra especializada', '✓  Configuração e testes', '✓  Orientação de uso', '✓  Suporte técnico'].forEach((line, i) => {
      ctx.fillText(line, margin + 28, y + 90 + i * 38);
    });

    const rightX = margin + half + gap + 28;
    ctx.fillStyle = TEXT;
    ctx.font = '900 25px Arial, sans-serif';
    ctx.fillText('CONDIÇÕES DE PAGAMENTO', rightX, y + 48);
    ctx.fillStyle = TEXT;
    ctx.font = '600 21px Arial, sans-serif';
    wrapText(quote.paymentTerms || 'A combinar', rightX, y + 85, half - 56, 28, 3);
    ctx.fillStyle = TEXT;
    ctx.font = '900 23px Arial, sans-serif';
    ctx.fillText('GARANTIA', rightX, y + 150);
    ctx.font = '600 20px Arial, sans-serif';
    wrapText(quote.warrantyInfo || 'Conforme serviço contratado.', rightX, y + 182, half - 56, 27, 3);
    if (quote.notes) {
      ctx.fillStyle = TEXT;
      ctx.font = '900 23px Arial, sans-serif';
      ctx.fillText('OBSERVAÇÕES', rightX, y + 248);
      ctx.fillStyle = MUTED;
      ctx.font = '500 18px Arial, sans-serif';
      wrapText(quote.notes, rightX, y + 278, half - 56, 24, 4);
    }

    // Benefícios
    y += infoH + 48;
    ctx.fillStyle = TEXT;
    ctx.font = '900 22px Arial, sans-serif';
    const benefits = [
      ['MAIS SEGURANÇA', 'Controle de acesso na sua mão.'],
      ['MAIS PRATICIDADE', 'Sem chaves, mais comodidade.'],
      ['SOLUÇÃO SOB MEDIDA', 'Ideal para residências e empresas.'],
      ['SUPORTE SEMPRE', 'Conte comigo após a instalação.'],
    ];
    const bw = contentWidth / 4;
    benefits.forEach(([title, desc], i) => {
      const bx = margin + bw * i;
      ctx.fillStyle = CYAN;
      ctx.beginPath();
      ctx.arc(bx + bw / 2, y + 28, 13, 0, Math.PI * 2);
      ctx.fill();
      ctx.textAlign = 'center';
      ctx.fillStyle = TEXT;
      ctx.font = '900 19px Arial, sans-serif';
      ctx.fillText(title, bx + bw / 2, y + 72);
      ctx.fillStyle = MUTED;
      ctx.font = '500 17px Arial, sans-serif';
      wrapText(desc, bx + 15, y + 105, bw - 30, 22, 2);
      ctx.textAlign = 'left';
    });

    // Rodapé
    const footerY = height - 150;
    ctx.fillStyle = DARK;
    ctx.fillRect(0, footerY, width, 150);
    ctx.fillStyle = '#26d366';
    ctx.font = '900 31px Arial, sans-serif';
    ctx.fillText('WhatsApp', margin, footerY + 55);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 31px Arial, sans-serif';
    ctx.fillText('(47) 93388-6303', margin, footerY + 98);
    ctx.textAlign = 'right';
    ctx.fillStyle = '#ffffff';
    ctx.font = '800 26px Arial, sans-serif';
    ctx.fillText('JOINVILLE - SC', width - margin, footerY + 62);
    ctx.fillStyle = '#aab4bf';
    ctx.font = '500 19px Arial, sans-serif';
    ctx.fillText('ATENDIMENTO EM TODA A REGIÃO', width - margin, footerY + 98);
    ctx.textAlign = 'left';

    return canvas;
  };

  const buildPdfBlob = async (canvas: HTMLCanvasElement) => {
    const jpegBlob = await new Promise<Blob>((resolve, reject) => {
      canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('Falha ao criar imagem para PDF.'))), 'image/jpeg', 0.94);
    });
    const jpeg = new Uint8Array(await jpegBlob.arrayBuffer());
    const pageWidth = 595.28;
    const pageHeight = pageWidth * (canvas.height / canvas.width);
    const encoder = new TextEncoder();
    const chunks: Uint8Array[] = [];
    const offsets: number[] = [0];
    let length = 0;
    const push = (data: string | Uint8Array) => {
      const bytes = typeof data === 'string' ? encoder.encode(data) : data;
      chunks.push(bytes);
      length += bytes.length;
    };
    const addObject = (id: number, bodyStart: string, binary?: Uint8Array, bodyEnd = '') => {
      offsets[id] = length;
      push(`${id} 0 obj\n${bodyStart}`);
      if (binary) push(binary);
      push(`${bodyEnd}\nendobj\n`);
    };

    push('%PDF-1.4\n%PDFBIN\n');
    addObject(1, '<< /Type /Catalog /Pages 2 0 R >>');
    addObject(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
    addObject(3, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth.toFixed(2)} ${pageHeight.toFixed(2)}] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>`);
    addObject(4, `<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`, jpeg, '\nendstream');
    const content = `q ${pageWidth.toFixed(2)} 0 0 ${pageHeight.toFixed(2)} 0 0 cm /Im1 Do Q`;
    addObject(5, `<< /Length ${encoder.encode(content).length} >>\nstream\n${content}\nendstream`);

    const xrefOffset = length;
    push('xref\n0 6\n0000000000 65535 f \n');
    for (let id = 1; id <= 5; id += 1) push(`${String(offsets[id]).padStart(10, '0')} 00000 n \n`);
    push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`);

    return new Blob(chunks, { type: 'application/pdf' });
  };

  const handleDownloadImage = async () => {
    try {
      setExporting('image');
      const canvas = await capture();
      const link = document.createElement('a');
      link.download = `orcamento-${quote.code}-${sanitizeFileName(quote.clientName || 'cliente')}.png`;
      link.href = canvas.toDataURL('image/png', 1);
      link.click();
    } catch (error) {
      console.error(error);
      alert('Não foi possível gerar a imagem do orçamento. Tente novamente.');
    } finally {
      setExporting(null);
    }
  };

  const handleDownloadPdf = async () => {
    try {
      setExporting('pdf');
      const canvas = await capture();
      const pdfBlob = await buildPdfBlob(canvas);
      const url = URL.createObjectURL(pdfBlob);
      const link = document.createElement('a');
      link.download = `orcamento-${quote.code}-${sanitizeFileName(quote.clientName || 'cliente')}.pdf`;
      link.href = url;
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(url), 1500);
    } catch (error) {
      console.error(error);
      alert('Não foi possível gerar o PDF do orçamento. Tente novamente.');
    } finally {
      setExporting(null);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black/90 px-2 py-3 backdrop-blur-sm sm:px-4">
      <div className="mx-auto flex min-h-full w-full max-w-4xl flex-col items-center justify-center gap-3">
        <div className="sticky top-2 z-10 flex w-full max-w-[760px] flex-wrap items-center justify-between gap-2 rounded-2xl border border-zinc-800 bg-zinc-950/95 p-2.5 shadow-2xl backdrop-blur-xl">
          <div className="flex min-w-0 items-center gap-2">
            <div className="rounded-xl border border-cyan-900 bg-cyan-950 p-2 text-cyan-400">
              <FileText className="h-4 w-4" />
            </div>
            <div className="min-w-0">
              <div className="truncate text-xs font-black text-white">Orçamento #{quote.code}</div>
              <div className="truncate text-[10px] text-zinc-500">{quote.clientName}</div>
            </div>
          </div>

          <div className="flex flex-wrap items-center justify-end gap-1.5">
            <button
              onClick={handleDownloadImage}
              disabled={!!exporting}
              className="inline-flex items-center gap-1.5 rounded-xl bg-cyan-500 px-3 py-2 text-[11px] font-black text-black transition hover:bg-cyan-400 disabled:opacity-50"
            >
              <ImageDown className="h-3.5 w-3.5" />
              {exporting === 'image' ? 'Gerando...' : 'Imagem'}
            </button>
            <button
              onClick={handleDownloadPdf}
              disabled={!!exporting}
              className="inline-flex items-center gap-1.5 rounded-xl bg-zinc-800 px-3 py-2 text-[11px] font-bold text-white transition hover:bg-zinc-700 disabled:opacity-50"
            >
              <Download className="h-3.5 w-3.5" />
              {exporting === 'pdf' ? 'Gerando...' : 'PDF'}
            </button>
            <button
              onClick={onClose}
              className="rounded-xl bg-zinc-900 p-2 text-zinc-400 transition hover:bg-zinc-800 hover:text-white"
              aria-label="Fechar"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        <div className="w-full overflow-x-auto rounded-[28px]">
          <div
            ref={documentRef}
            id="quote-document"
            className="mx-auto w-full max-w-[760px] overflow-hidden rounded-[26px] bg-white text-slate-900 shadow-2xl"
          >
            <header className="relative min-h-[205px] overflow-hidden bg-[#06090d] px-6 pb-6 pt-5 text-white sm:px-8">
              <div className="absolute inset-y-0 right-0 w-[42%] bg-[linear-gradient(135deg,transparent_0%,rgba(0,169,224,0.06)_28%,rgba(0,169,224,0.25)_29%,rgba(0,169,224,0.08)_48%,transparent_49%)]" />
              <div className="absolute -right-10 -top-12 h-56 w-56 rounded-full border-[28px] border-cyan-500/10" />
              <div className="absolute right-7 top-5 hidden sm:block">
                <svg viewBox="0 0 180 180" className="h-40 w-40 opacity-95" aria-hidden="true">
                  <defs>
                    <linearGradient id="lockBody" x1="0" y1="0" x2="1" y2="1">
                      <stop offset="0" stopColor="#242a31" />
                      <stop offset="0.55" stopColor="#0d1116" />
                      <stop offset="1" stopColor="#030507" />
                    </linearGradient>
                  </defs>
                  <rect x="58" y="8" width="66" height="162" rx="22" fill="url(#lockBody)" stroke="#4b5563" strokeWidth="2" />
                  <rect x="73" y="28" width="36" height="62" rx="7" fill="#020406" stroke="#1f2937" />
                  <g fill="#e5e7eb" fontSize="10" fontFamily="Arial" textAnchor="middle">
                    <text x="81" y="48">1</text><text x="91" y="48">2</text><text x="101" y="48">3</text>
                    <text x="81" y="64">4</text><text x="91" y="64">5</text><text x="101" y="64">6</text>
                    <text x="81" y="80">7</text><text x="91" y="80">8</text><text x="101" y="80">9</text>
                  </g>
                  <circle cx="91" cy="124" r="17" fill="#151b22" stroke="#98a2ad" strokeWidth="3" />
                  <circle cx="91" cy="124" r="7" fill="#030507" stroke="#64748b" />
                  <rect x="102" y="117" width="54" height="15" rx="7.5" fill="#10151b" stroke="#4b5563" />
                </svg>
              </div>

              <div className="relative z-[1] flex items-start justify-between gap-3">
                <img
                  src={MAICON_LOGO}
                  alt="Maicon Automação"
                  className="h-[90px] w-[250px] max-w-[65%] object-contain object-left"
                />
                <div className="sm:pr-36 text-right">
                  <div className="text-[9px] font-bold uppercase tracking-[0.22em] text-zinc-400">Tecnologia e segurança</div>
                  <div className="mt-1 h-0.5 w-14 bg-cyan-400 ml-auto" />
                </div>
              </div>

              <div className="relative z-[1] mt-4 max-w-[68%]">
                <div className="text-[11px] font-bold uppercase tracking-[0.28em] text-cyan-400">Proposta comercial</div>
                <h1 className="mt-1 text-4xl font-black tracking-tight sm:text-5xl">ORÇAMENTO</h1>
                <p className="mt-1 text-[11px] uppercase tracking-[0.26em] text-zinc-300">Soluções em fechaduras eletrônicas</p>
              </div>
            </header>

            <main className="space-y-5 px-5 py-5 sm:px-8 sm:py-7">
              <section className="grid grid-cols-1 gap-3 sm:grid-cols-[1.15fr_.85fr]">
                <div className="overflow-hidden rounded-2xl border border-slate-200 bg-slate-50">
                  <div className="grid grid-cols-[44px_1fr] border-b border-slate-200 p-3.5">
                    <div className="flex items-start justify-center pt-0.5 text-cyan-600"><Smartphone className="h-5 w-5" /></div>
                    <div><div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Cliente</div><div className="mt-0.5 text-[14px] font-black text-slate-900">{quote.clientName}</div></div>
                  </div>
                  <div className="grid grid-cols-[44px_1fr] border-b border-slate-200 p-3.5">
                    <div className="flex items-start justify-center pt-0.5 text-cyan-600"><Phone className="h-5 w-5" /></div>
                    <div><div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Contato</div><div className="mt-0.5 text-[13px] font-semibold">{quote.clientPhone || 'Não informado'}</div></div>
                  </div>
                  <div className="grid grid-cols-[44px_1fr] p-3.5">
                    <div className="flex items-start justify-center pt-0.5 text-cyan-600"><MapPin className="h-5 w-5" /></div>
                    <div>
                      <div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Endereço</div>
                      <div className="mt-0.5 text-[13px] font-semibold">{quote.address || 'A combinar'}</div>
                      {(quote.neighborhood || quote.city) && <div className="mt-0.5 text-[11px] text-slate-500">{[quote.neighborhood && `Bairro: ${quote.neighborhood}`, quote.city && `Cidade: ${quote.city}`].filter(Boolean).join('  |  ')}</div>}
                    </div>
                  </div>
                </div>

                <div className="overflow-hidden rounded-2xl border border-slate-200 bg-slate-50">
                  <div className="border-b border-slate-200 p-3.5">
                    <div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Data do orçamento</div>
                    <div className="mt-0.5 text-[13px] font-black">{formatDateBR(quote.date)}</div>
                  </div>
                  <div className="border-b border-slate-200 p-3.5">
                    <div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Validade</div>
                    <div className="mt-0.5 flex items-baseline gap-2"><span className="text-[13px] font-black">{quote.validityDays} dias</span><span className="text-[10px] text-slate-500">até {formatDateBR(validUntil)}</span></div>
                  </div>
                  <div className="p-3.5">
                    <div className="flex items-center justify-between gap-2">
                      <div>
                        <div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Nº do orçamento</div>
                        <div className="mt-0.5 text-[13px] font-black">{quote.code}</div>
                      </div>
                      {getStatusBadge(quote.status)}
                    </div>
                  </div>
                </div>
              </section>

              <section className="overflow-hidden rounded-2xl border border-slate-200">
                <div className="grid grid-cols-[34px_1fr_90px] bg-[#0a0e13] px-3 py-2.5 text-[9px] font-black uppercase tracking-wider text-white sm:grid-cols-[38px_1fr_110px_105px]">
                  <div>Item</div><div>Descrição do serviço / produto</div><div className="hidden sm:block text-center">Garantia</div><div className="text-right">Valor</div>
                </div>
                <div className="divide-y divide-slate-200 bg-white">
                  {quote.items.map((item, index) => (
                    <div key={item.id} className="grid grid-cols-[34px_1fr_90px] items-center px-3 py-3 text-[11px] sm:grid-cols-[38px_1fr_110px_105px]">
                      <div className="font-black text-slate-500">{index + 1}</div>
                      <div className="pr-2 font-semibold text-slate-800">{item.description} {item.quantity > 1 ? `(${item.quantity}x)` : ''}</div>
                      <div className="hidden text-center text-[10px] text-slate-500 sm:block">{quote.warrantyInfo || '—'}</div>
                      <div className="text-right font-black">{formatCurrencyBRL(item.total)}</div>
                    </div>
                  ))}
                </div>
                <div className="flex items-center justify-end border-t border-slate-200 bg-slate-50 px-4 py-3">
                  <div className="flex min-w-[235px] items-stretch overflow-hidden rounded-xl border border-slate-200">
                    <div className="flex items-center bg-white px-4 text-[11px] font-black uppercase text-slate-700">Total</div>
                    <div className="flex-1 bg-cyan-500 px-4 py-2.5 text-right text-[19px] font-black text-white">{formatCurrencyBRL(quote.totalAmount)}</div>
                  </div>
                </div>
              </section>

              <section className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-wider text-slate-800"><Wrench className="h-4 w-4 text-cyan-600" /> Incluso no serviço</div>
                  <div className="mt-3 space-y-2 text-[11px] text-slate-600">
                    {['Mão de obra especializada', 'Configuração e testes', 'Orientação de uso', 'Suporte técnico'].map((text) => <div key={text} className="flex items-center gap-2"><CheckCircle2 className="h-3.5 w-3.5 shrink-0 text-cyan-600" /><span>{text}</span></div>)}
                  </div>
                </div>
                <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                  <div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Condições de pagamento</div>
                  <div className="mt-1 text-[12px] font-semibold text-slate-800">{quote.paymentTerms || 'A combinar'}</div>
                  <div className="mt-3 border-t border-slate-200 pt-3">
                    <div className="flex items-center gap-1.5 text-[9px] font-black uppercase tracking-wider text-slate-500"><ShieldCheck className="h-3.5 w-3.5 text-cyan-600" /> Garantia</div>
                    <div className="mt-1 text-[11px] font-semibold text-slate-800">{quote.warrantyInfo || 'Conforme serviço contratado.'}</div>
                  </div>
                  {quote.notes && <div className="mt-3 border-t border-slate-200 pt-3"><div className="text-[9px] font-black uppercase tracking-wider text-slate-500">Observações</div><div className="mt-1 whitespace-pre-wrap text-[10px] leading-relaxed text-slate-600">{quote.notes}</div></div>}
                </div>
              </section>

              <section className="grid grid-cols-2 gap-2 border-t border-slate-200 pt-4 sm:grid-cols-4">
                {[
                  [ShieldCheck, 'Mais segurança', 'Controle de acesso na sua mão.'],
                  [Smartphone, 'Mais praticidade', 'Sem chaves, mais comodidade.'],
                  [Home, 'Residências e empresas', 'Soluções para cada necessidade.'],
                  [Sparkles, 'Suporte sempre', 'Conte comigo após a instalação.'],
                ].map(([Icon, title, subtitle]: any) => (
                  <div key={title} className="px-2 py-2 text-center">
                    <Icon className="mx-auto h-5 w-5 text-cyan-600" />
                    <div className="mt-1.5 text-[9px] font-black uppercase text-slate-800">{title}</div>
                    <div className="mt-0.5 text-[8px] leading-tight text-slate-500">{subtitle}</div>
                  </div>
                ))}
              </section>
            </main>

            <footer className="grid grid-cols-1 items-center gap-3 bg-[#06090d] px-6 py-5 text-white sm:grid-cols-[1fr_auto_1fr] sm:px-8">
              <div className="text-center sm:text-left">
                <div className="text-[9px] uppercase tracking-[0.18em] text-zinc-500">WhatsApp</div>
                <div className="mt-0.5 text-[16px] font-black text-emerald-400">(47) 93388-6303</div>
              </div>
              <img src={MAICON_LOGO} alt="Maicon Automação" className="mx-auto h-14 w-36 object-contain" />
              <div className="text-center sm:text-right">
                <div className="text-[9px] uppercase tracking-[0.18em] text-zinc-500">Atendimento</div>
                <div className="mt-0.5 text-[12px] font-black">JOINVILLE - SC</div>
              </div>
            </footer>
          </div>
        </div>

        <div className="w-full max-w-[760px] rounded-2xl border border-zinc-800 bg-zinc-950 p-3">
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            <button onClick={() => onEditQuote(quote)} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-zinc-800 px-3 py-2.5 text-[11px] font-bold text-white hover:bg-zinc-700"><Pencil className="h-3.5 w-3.5" /> Editar</button>
            <button onClick={() => onOpenWhatsApp(quote)} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-emerald-600 px-3 py-2.5 text-[11px] font-black text-white hover:bg-emerald-500"><MessageSquare className="h-3.5 w-3.5" /> WhatsApp</button>
            <button onClick={handleDownloadImage} disabled={!!exporting} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-cyan-500 px-3 py-2.5 text-[11px] font-black text-black hover:bg-cyan-400 disabled:opacity-50"><ImageDown className="h-3.5 w-3.5" /> Imagem</button>
            {quote.status !== 'convertido' ? (
              <button onClick={() => onConvertToAppointment(quote)} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-blue-600 px-3 py-2.5 text-[11px] font-black text-white hover:bg-blue-500"><CalendarPlus className="h-3.5 w-3.5" /> Agendar</button>
            ) : (
              <button onClick={handleDownloadPdf} disabled={!!exporting} className="inline-flex items-center justify-center gap-1.5 rounded-xl bg-zinc-800 px-3 py-2.5 text-[11px] font-bold text-white hover:bg-zinc-700 disabled:opacity-50"><Download className="h-3.5 w-3.5" /> PDF</button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
